# Fresh computation of minimum sample size
alpha <- 0.05
target_power <- 0.80
partial_eta_sq <- 0.06
num_cells <- 6
df_numerator <- 1

compute_power <- function(n) {
  df_error <- num_cells * (n - 1)
  f_crit <- qf(1 - alpha, df1 = df_numerator, df2 = df_error)
  lambda <- (partial_eta_sq / (1 - partial_eta_sq)) * df_error
  power <- 1 - pf(f_crit, df1 = df_numerator, df2 = df_error, ncp = lambda)
  return(power)
}

# Binary search
n_min <- 1
n_max <- 500

while (n_max - n_min > 1) {
  n_mid <- (n_min + n_max) %/% 2
  if (compute_power(n_mid) < target_power) {
    n_min <- n_mid
  } else {
    n_max <- n_mid
  }
}

# Result
sample_size <- n_max

cat("Sample size result:", sample_size, "\n")

POWER_AGENT_RESULT=jsonlite::toJSON(
  list(
    results = list(
      list(metric = "sample_size", value = sample_size, unit = "participants_per_cell")
    )
  ),
  auto_unbox = TRUE,
  digits = 15
)

